 "content": "def transform(grid):
    """Recolor full-width/full-height separator lines to 2."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # ARC separators are uniform rows or columns. The surrounding field
    # color is the most frequent color; keep isolated marks untouched.
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != bg:
            out[r] = [2] * w
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if len(set(vals)) == 1 and vals[0] != bg:
            for r in range(h):
                out[r][c] = 2
    return out
